using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        var path = args[0];
        var build = BinaryLog.ReadBuild(path);

        // Find all warnings too
        Console.WriteLine("=== WARNINGS ===");
        build.VisitAllChildren<Warning>(w => {
            var proj = "";
            var node = w.Parent;
            while (node != null) {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent;
            }
            if (w.Code != null && (w.Code.StartsWith("CS") || w.Code.StartsWith("NU")))
                Console.WriteLine($"  [{w.Code}] {proj}: {w.Text}");
        });

        // Check for failed projects (dependency failures)
        Console.WriteLine();
        Console.WriteLine("=== BUILD RESULT ===");
        Console.WriteLine($"Build succeeded: {build.Succeeded}");

        // Look at project references
        Console.WriteLine();
        Console.WriteLine("=== PROJECTS ===");
        build.VisitAllChildren<Project>(p => {
            Console.WriteLine($"  {p.Name} - Succeeded: {p.Succeeded}");
        });
    }
}
