using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        var path = args[0];
        var build = BinaryLog.ReadBuild(path);

        // Dump all items that look like package references
        Console.WriteLine("=== ALL ITEMS WITH 'Package' ===");
        build.VisitAllChildren<AddItem>(item => {
            var proj = "";
            var node = (BaseNode)item;
            while (node != null) {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent as BaseNode;
            }
            if (item.Name != null && item.Name.Contains("PackageReference"))
                Console.WriteLine($"  [{proj}] {item.Name} -> {string.Join(", ", item.Children.Select(c => c.ToString()))}");
        });

        Console.WriteLine();
        Console.WriteLine("=== NAMED NODES (messages with Newtonsoft) ===");
        build.VisitAllChildren<Message>(m => {
            if (m.Text != null && m.Text.Contains("Newtonsoft"))
                Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
        });
    }
}
EOF
