using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        var path = args[0];
        var build = BinaryLog.ReadBuild(path);

        // Look for the source file content or references in the tree
        Console.WriteLine("=== SOURCE FILES ===");
        var seen = new HashSet<string>();
        build.VisitAllChildren<Item>(item => {
            if (item.Text != null && item.Text.Contains(".cs") && !item.Text.Contains("obj/"))
            {
                if (seen.Add(item.Text))
                    Console.WriteLine($"  {item.Text}");
            }
        });

        // Look at the csproj content embedded
        Console.WriteLine();
        Console.WriteLine("=== LOOKING FOR CSPROJ CONTENT ===");
        build.VisitAllChildren<Message>(m => {
            if (m.Text != null && m.Text.Contains("PackageReference") && m.Text.Contains("Include"))
                Console.WriteLine($"  {m.Text.Substring(0, Math.Min(300, m.Text.Length))}");
        });

        // Check NamedNode for property info
        Console.WriteLine();
        Console.WriteLine("=== PROPERTIES ===");
        build.VisitAllChildren<Property>(p => {
            var proj = "";
            var node = (BaseNode)p;
            while (node != null) {
                if (node is Project pr) { proj = pr.Name; break; }
                node = node.Parent as BaseNode;
            }
            if (proj.Contains("Services") && p.Name != null && p.Name.Contains("Package"))
                Console.WriteLine($"  {p.Name} = {p.Value}");
        });
    }
