using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        var path = args[0];
        var build = BinaryLog.ReadBuild(path);

        // Dump the tree structure for Services.csproj evaluation
        Console.WriteLine("=== TREE WALK (depth-limited) ===");
        bool foundServices = false;
        build.VisitAllChildren<Project>(p => {
            if (!foundServices && p.Name == "Services.csproj")
            {
                foundServices = true;
                PrintTree(p, 0, 3);
            }
        });
    }

    static void PrintTree(BaseNode node, int depth, int maxDepth)
    {
        if (depth > maxDepth) return;
        var indent = new string(' ', depth * 2);
        var type = node.GetType().Name;
        Console.WriteLine($"{indent}[{type}] {node.ToString()?.Substring(0, Math.Min(120, node.ToString()?.Length ?? 0))}");
        if (node is TreeNode tn)
        {
            foreach (var child in tn.Children.Take(30))
            {
                if (child is BaseNode bn)
                    PrintTree(bn, depth + 1, maxDepth);
            }
        }
    }
}
