                                foreach (var param in f.Children)
                                {
                                    if (param is Parameter pp)
                                    {
                                        if (pp.Name == "Sources")
                                        {
                                            Console.WriteLine("=== SOURCES ===");
                                            foreach (var item in pp.Children)
                                                Console.WriteLine($"  {item}");
                                        }
                                        else if (pp.Name == "References")
                                        {
                                            Console.WriteLine("=== REFERENCES (checking for Newtonsoft) ===");
                                            bool found = false;
                                            foreach (var item in pp.Children)
                                            {
                                                var s = item.ToString() ?? "";
                                                if (s.Contains("Newtonsoft"))
                                                {
                                                    found = true;
                                                    Console.WriteLine($"  FOUND: {s}");
                                                }
                                            }
                                            if (!found)
                                                Console.WriteLine("  Newtonsoft.Json NOT found in references!");
                                            Console.WriteLine($"  Total references: {pp.Children.Count}");
                                        }
                                    }
                                }
                            }
                        }
                    }
                });
            }
        });

        // Also check evaluation properties for Services project - TargetFramework
        Console.WriteLine();
        Console.WriteLine("=== KEY PROPERTIES (Services.csproj) ===");
        bool doneProps = false;
        build.VisitAllChildren<Project>(p => {
            if (!doneProps && p.Name == "Services.csproj")
            {
                p.VisitAllChildren<Property>(prop => {
                    if (prop.Name == "TargetFramework" || prop.Name == "TargetFrameworks")
                        Console.WriteLine($"  {prop.Name} = {prop.Value}");
                });
                // Only check one instance that has evaluation data
                var propFolder = p.Children.OfType<Folder>().FirstOrDefault(f => f.Name == "Properties");
                if (propFolder != null)
                {
                    foreach (var sub in propFolder.Children.OfType<Folder>())
                    {
                        foreach (var prop in sub.Children.OfType<Property>())
                        {
                            if (prop.Name == "TargetFramework" || prop.Name == "TargetFrameworks" || 
                                prop.Name == "ProjectAssetsFile")
                                Console.WriteLine($"  [{sub.Name}] {prop.Name} = {prop.Value}");
                        }
