class Program
{
    static void Main(string[] args)
    {
        var path = args[0];
        var build = BinaryLog.ReadBuild(path);

        // Check if Api.csproj or Core.csproj have errors
        Console.WriteLine("=== ERRORS BY PROJECT ===");
        build.VisitAllChildren<Error>(e => {
            var proj = "";
            var node = (BaseNode)e;
            while (node != null) {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent as BaseNode;
            }
            Console.WriteLine($"  [{proj}] {e.Code}: {e.Text?.Substring(0, Math.Min(120, e.Text?.Length ?? 0))}");
        });

        // Check project references for Api (does it reference Services?)
        Console.WriteLine();
        Console.WriteLine("=== PROJECT REFERENCES ===");
        build.VisitAllChildren<Project>(p => {
            if (p.Name == "Api.csproj")
            {
                p.VisitAllChildren<AddItem>(ai => {
                    if (ai.Name == "ProjectReference" || ai.Name == "_MSBuildProjectReferenceExistent")
                    {
                        foreach (var item in ai.Children.OfType<Item>())
                            Console.WriteLine($"  [Api] {ai.Name}: {item.Text}");
                    }
                });
                break;
            }
        });

        build.VisitAllChildren<Project>(p => {
            if (p.Name == "Services.csproj")
            {
                p.VisitAllChildren<AddItem>(ai => {
                    if (ai.Name == "ProjectReference" || ai.Name == "_MSBuildProjectReferenceExistent")
                    {
                        foreach (var item in ai.Children.OfType<Item>())
                            Console.WriteLine($"  [Services] {ai.Name}: {item.Text}");
                    }
                });
                break;
            }
        });
    }
}
